package gallery

const conversionIndexHTML = `
<header class="max-w-3xl">
  <p class="text-sm font-medium text-accent">PRIVATE DESIGN REFERENCES</p>
  <h1 class="mt-2 text-3xl font-semibold">Saved conversions</h1>
  <p class="mt-3 text-ink-muted">Inspect a saved translation beside its original source. Keep the original renderer available whenever a conversion does not fit the application.</p>
</header>
<nav aria-label="Private library" class="mt-6 flex flex-wrap gap-5 text-sm"><a href="{{.Originals}}" class="text-accent underline underline-offset-4">Originals</a><span aria-current="page" class="font-medium">Saved conversions</span></nav>
<form action="/conversions" method="get" role="search" aria-label="Saved conversion filters" class="mt-8 grid gap-4 border-y border-line py-5 sm:grid-cols-2 lg:grid-cols-3">
  {{if .Theme}}<input type="hidden" name="theme" value="{{.Theme}}">{{end}}
  <input type="hidden" name="limit" value="{{.Query.Limit}}">
  <div class="min-w-0"><label for="conversion-archive" class="block text-sm font-medium">Original archive</label><select id="conversion-archive" name="archive_id" class="mt-2 w-full min-w-0 rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"><option value="">All saved archives</option>{{range .Archives}}<option value="{{.ID}}"{{if eq $.Query.ArchiveID .ID}} selected{{end}}>{{.Label}}</option>{{end}}</select></div>
  <div class="min-w-0"><label for="conversion-path" class="block text-sm font-medium">Exact source path</label><input id="conversion-path" name="path" value="{{.Query.Path}}" placeholder="Paste a complete member path" class="mt-2 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"></div>
  <div><label for="conversion-status" class="block text-sm font-medium">Translation result</label><select id="conversion-status" name="status" class="mt-2 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"><option value="">All results</option><option value="translated"{{if eq .Query.Status "translated"}} selected{{end}}>Translated source</option><option value="unsupported"{{if eq .Query.Status "unsupported"}} selected{{end}}>Requires adaptation</option></select></div>
  <div class="flex flex-wrap items-center gap-4 sm:col-span-2 lg:col-span-3"><button class="rounded-md bg-accent px-4 py-2 font-medium text-accent-ink hover:bg-accent-hover focus-visible:outline-2 focus-visible:outline-focus focus-visible:outline-offset-2">Find conversions</button><a href="{{.Reset}}" class="text-sm text-ink-muted underline underline-offset-4">Reset filters</a></div>
</form>
<section class="mt-8" aria-labelledby="conversion-results">
  <div class="flex flex-wrap items-baseline justify-between gap-2"><h2 id="conversion-results" class="text-lg font-semibold">{{.Page.Total}} matching attempts</h2><p class="text-xs text-ink-muted">Metadata only. Open a comparison for integrity and replay checks.</p></div>
  <div class="mt-3 border-t border-line">{{range .Rows}}
    <article class="grid min-w-0 gap-4 border-b border-line py-5 lg:grid-cols-3">
      <div class="min-w-0 lg:col-span-2"><p class="text-xs text-ink-muted">{{.Title}} · {{.Entry.Target}} syntax</p><h3 class="mt-2 break-all font-mono text-sm font-semibold"><a href="{{.Compare}}" class="text-accent underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-focus">{{.Entry.Source.Path}}</a></h3><p class="mt-2 text-sm">{{.Status}}</p><p class="mt-1 text-xs text-ink-muted">Target compatibility: not verified</p></div>
      <div class="flex flex-wrap items-start gap-4 text-sm lg:justify-end"><a href="{{.Compare}}" class="text-accent underline underline-offset-4">Compare source<span class="sr-only"> for {{.Entry.Source.Path}}</span></a><a href="{{.Original}}" class="text-accent underline underline-offset-4">Open original<span class="sr-only"> {{.Entry.Source.Path}}</span></a></div>
    </article>
  {{else}}<div class="py-10"><h3 class="font-semibold">No saved conversions match</h3><p class="mt-3 max-w-2xl text-sm text-ink-muted">Original references remain available. Save an explicit syntax attempt with <code>appkit data assets-translate -id ARCHIVE_ID -path EXACT_MEMBER_PATH -save</code>, then return here. Browsing never creates a store or runs source code.</p><div class="mt-4 flex flex-wrap gap-5 text-sm"><a href="{{.Reset}}" class="text-accent underline">Clear filters</a><a href="{{.Originals}}" class="text-accent underline">Browse original references</a></div></div>{{end}}</div>
  {{if .Next}}<a href="{{.Next}}" class="mt-5 inline-block rounded-md border border-line-strong px-4 py-2 text-accent focus-visible:outline-2 focus-visible:outline-focus">Next page →</a>{{end}}
</section>
<aside class="mt-8 max-w-3xl border-t border-line pt-6"><h2 class="font-semibold">A translation is not a tested UI</h2><p class="mt-2 text-sm text-ink-muted">Every attempt remains <code>not-verified</code> for target compatibility. These attempts do not certify appearance, accessibility, behavior, security or performance. Unsupported interactions need a reviewed adapter or the source-native runtime. Both choices keep their original provenance.</p></aside>
<details class="mt-8 text-xs text-ink-muted"><summary class="cursor-pointer">Shared attempt index and privacy</summary><p class="mt-2 break-all font-mono">{{.Page.Revision}}</p><p class="mt-2">Gallery, CLI and MCP share these IDs and this revision. Saved source stays in the private, Git-ignored store. Do not publish this library or its contents.</p></details>
`

const conversionDetailHTML = `
<a href="{{.Back}}" class="text-sm text-accent underline underline-offset-4">← Saved conversions</a>
<header class="mt-5 max-w-3xl"><p class="text-sm font-medium text-accent">PRIVATE SOURCE COMPARISON</p><h1 class="mt-2 text-3xl font-semibold">Original and converted source</h1><p class="mt-3 break-all font-mono text-sm">{{.Detail.Entry.Source.Path}}</p><p class="mt-3 text-ink-muted">This compares source, not appearance or behavior. No vendor or generated code is executed here.</p></header>
<section class="mt-6 border-y border-line py-5" aria-labelledby="conversion-evidence"><h2 id="conversion-evidence" class="text-lg font-semibold">{{.Status}} · target compatibility not verified</h2><p class="mt-3 text-sm font-medium">{{.Replay}}</p><p class="mt-2 max-w-3xl text-sm text-ink-muted">{{.ReplayNotice}}</p><p class="mt-2 max-w-3xl text-sm text-ink-muted">Compilation, visual fidelity, interaction, accessibility, security, performance and consumer integration require separate evidence.</p></section>
<nav aria-label="Comparison actions" class="mt-5 flex flex-wrap gap-5 text-sm"><a href="{{.Original}}" class="text-accent underline underline-offset-4">Open original reference</a>{{if .Detail.Translation.Artifact}}<a href="{{.Download}}" class="text-accent underline underline-offset-4">Download saved .templ source</a>{{end}}<a href="{{.ReceiptJSON}}" class="text-accent underline underline-offset-4">Read complete receipt as JSON</a></nav>
{{if .PreparedComparison}}<p class="mt-4 text-sm"><a href="{{.PreparedComparison}}" class="text-accent underline underline-offset-4">Inspect the prepared pricing comparison</a><span class="text-ink-muted"> · original and compiled markup in one chosen environment, not a certified portal match</span></p>{{end}}
<form action="{{.Route}}" method="get" aria-label="Source line windows" class="mt-6 grid items-end gap-4 border-b border-line pb-5 sm:grid-cols-2 xl:grid-cols-4">
  {{range .Context}}<input type="hidden" name="{{.Name}}" value="{{.Value}}">{{end}}
  <div><label for="conversion-source-line" class="block text-sm font-medium">Original start line</label><input id="conversion-source-line" type="number" name="source_line" min="1" max="{{.Source.Total}}" value="{{.Source.Start}}" required class="mt-2 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"></div>
  {{if .Detail.Translation.Artifact}}<div><label for="conversion-artifact-line" class="block text-sm font-medium">Converted start line</label><input id="conversion-artifact-line" type="number" name="artifact_line" min="1" max="{{.Artifact.Total}}" value="{{.Artifact.Start}}" required class="mt-2 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"></div>{{end}}
  <div><label for="conversion-lines" class="block text-sm font-medium">Lines per pane</label><input id="conversion-lines" type="number" name="lines" min="1" max="400" value="{{.Lines}}" required class="mt-2 w-full rounded-md border border-line-strong bg-surface-raised p-2 text-ink focus-visible:outline-2 focus-visible:outline-focus"></div>
  <button class="rounded-md bg-accent px-4 py-2 font-medium text-accent-ink hover:bg-accent-hover focus-visible:outline-2 focus-visible:outline-focus focus-visible:outline-offset-2">Show source lines</button>
</form>
<div class="mt-8 grid min-w-0 gap-8 xl:grid-cols-2">
  <section id="conversion-original" tabindex="-1" class="min-w-0" aria-labelledby="conversion-original-title">
    <h2 id="conversion-original-title" class="text-xl font-semibold">Original source</h2><p class="mt-2 text-xs text-ink-muted">{{.Detail.Entry.Source.Size}} bytes · original archive and member verified</p>
    <p class="mt-4 text-xs text-ink-muted">Lines {{.Source.Start}}–{{.Source.End}} of {{.Source.Total}}</p>
    {{if .Source.TooLarge}}<p class="mt-3 text-sm text-ink-muted">This line window exceeds the 32 KiB display limit. No source was truncated. Use fewer lines or read the complete original as JSON.</p>{{else}}<pre data-conversion-pane="source" tabindex="0" role="region" aria-label="Original source text" class="mt-3 max-h-[32rem] max-w-full overflow-auto rounded-md border border-line bg-surface-sunken p-4 font-mono text-xs leading-relaxed focus-visible:outline-2 focus-visible:outline-focus"><code>{{.Source.Content}}</code></pre>{{end}}
    <nav aria-label="Original source lines" class="mt-4 flex flex-wrap gap-5 text-sm">{{if .Source.Previous}}<a href="{{.Source.Previous}}" class="text-accent underline">Previous original lines</a>{{end}}{{if .Source.Next}}<a href="{{.Source.Next}}" class="text-accent underline">Next original lines</a>{{end}}<a href="{{.SourceJSON}}" class="text-accent underline">Full original JSON</a></nav>
  </section>
  <section id="conversion-artifact" tabindex="-1" class="min-w-0" aria-labelledby="conversion-artifact-title">
    <h2 id="conversion-artifact-title" class="text-xl font-semibold">Converted source</h2>
    {{if .Detail.Translation.Artifact}}<p class="mt-2 text-xs text-ink-muted">{{.Detail.Translation.Artifact.Filename}} · {{.Detail.Entry.Target}} · syntax only</p><p class="mt-4 text-xs text-ink-muted">Lines {{.Artifact.Start}}–{{.Artifact.End}} of {{.Artifact.Total}}</p>
      {{if .Artifact.TooLarge}}<p class="mt-3 text-sm text-ink-muted">This line window exceeds the 32 KiB display limit. No source was truncated. Use fewer lines or download the exact saved artifact.</p>{{else}}<pre data-conversion-pane="artifact" tabindex="0" role="region" aria-label="Converted source text" class="mt-3 max-h-[32rem] max-w-full overflow-auto rounded-md border border-line bg-surface-sunken p-4 font-mono text-xs leading-relaxed focus-visible:outline-2 focus-visible:outline-focus"><code>{{.Artifact.Content}}</code></pre>{{end}}
      <nav aria-label="Converted source lines" class="mt-4 flex flex-wrap gap-5 text-sm">{{if .Artifact.Previous}}<a href="{{.Artifact.Previous}}" class="text-accent underline">Previous converted lines</a>{{end}}{{if .Artifact.Next}}<a href="{{.Artifact.Next}}" class="text-accent underline">Next converted lines</a>{{end}}<a href="{{.Download}}" class="text-accent underline">Download complete source</a></nav>
    {{else}}<div class="mt-4 border-l-2 border-caution pl-4"><h3 class="font-medium">No artifact was emitted</h3><p class="mt-2 text-sm text-ink-muted">This source is outside the transformer's supported subset. Inspect the diagnostics below, then choose a reviewed adapter or keep the original runtime. An unsupported result does not discard the original design.</p><a href="{{.Original}}" class="mt-3 inline-block text-sm text-accent underline">Use the original reference</a></div>{{end}}
  </section>
</div>
{{if or .Detail.Translation.Diagnostics .Detail.Translation.OmittedDiagnostics}}<section class="mt-10 border-t border-line pt-6" aria-labelledby="conversion-diagnostics"><h2 id="conversion-diagnostics" class="text-xl font-semibold">Translation diagnostics</h2><p class="mt-2 text-sm text-ink-muted">Offsets refer to original source bytes. These are translation findings, not a complete runtime assessment.</p><ol class="mt-4 divide-y divide-line">{{range .Detail.Translation.Diagnostics}}<li class="py-3"><p class="break-all font-mono text-xs">{{.Code}} · byte {{.Offset}}</p><p class="mt-2 break-words text-sm text-ink-muted">{{.Message}}</p></li>{{end}}</ol>{{if .Detail.Translation.OmittedDiagnostics}}<p class="mt-3 text-sm text-ink-muted">{{.Detail.Translation.OmittedDiagnostics}} additional findings were omitted by the bounded translator. Fix the reported causes and run a new explicit attempt.</p>{{end}}</section>{{end}}
<details class="mt-10 border-t border-line pt-6 text-xs"><summary class="cursor-pointer font-medium">Exact provenance and verification limits</summary><dl class="mt-5 space-y-4 text-ink-muted">
  <div><dt>Attempt ID</dt><dd class="mt-1 break-all font-mono">{{.Detail.Entry.ID}}</dd></div>
  <div><dt>Original archive ID</dt><dd class="mt-1 break-all font-mono">{{.Detail.Entry.Source.ArchiveID}}</dd></div>
  <div><dt>Original member SHA-256</dt><dd class="mt-1 break-all font-mono">{{.Detail.Entry.Source.SHA256}}</dd></div>
  {{if .Detail.Translation.Artifact}}<div><dt>Saved artifact SHA-256</dt><dd class="mt-1 break-all font-mono">{{.Detail.Translation.Artifact.SHA256}}</dd></div>{{end}}
  <div><dt>Transformer / rule SHA-256</dt><dd class="mt-1 break-all font-mono">{{.Detail.Entry.Transformer.ID}} / {{.Detail.Entry.Transformer.SHA256}}</dd></div>
  <div><dt>Recorded translator toolchain</dt><dd class="mt-1 break-all font-mono">{{.Detail.Entry.Transformer.GoVersion}} · {{.Detail.Entry.Transformer.HTMLParser}}</dd></div>
  <div><dt>Required templ compiler, not proof of compilation</dt><dd class="mt-1 break-all font-mono">{{.Detail.Entry.Transformer.RequiredTempl}}</dd></div>
  <div><dt>Machine-readable status / replay / compatibility</dt><dd class="mt-1 break-all font-mono">{{.Detail.Entry.Status}} / {{.Detail.Replay}} / {{.Detail.Entry.Verification}}</dd></div>
  <div><dt>Shared attempt index revision</dt><dd class="mt-1 break-all font-mono">{{.Detail.Revision}}</dd></div>
</dl><p class="mt-5 max-w-3xl text-ink-muted">Private licensed derivative source. Preserve attribution and original access restrictions. A source comparison does not certify runtime compatibility or grant redistribution rights. No dependency installation, generated-code execution, preview or target certification occurs on these routes.</p></details>
`

const conversionProblemHTML = `
<div class="max-w-3xl"><p class="text-sm font-medium text-accent">PRIVATE SOURCE COMPARISON</p><h1 class="mt-2 text-3xl font-semibold">{{.Title}}</h1><p class="mt-4 text-ink-muted">{{.Message}}</p><div class="mt-6 flex flex-wrap gap-5"><a href="{{.Back}}" class="text-accent underline underline-offset-4">Return to saved conversions</a>{{if .Original}}<a href="{{.Original}}" class="text-accent underline underline-offset-4">Open original reference</a>{{end}}<a href="{{.Originals}}" class="text-accent underline underline-offset-4">Browse original library</a></div></div>
`
